"""
PreToolUse permission hook for Claude Code.

This script is called by Claude's PreToolUse hook before each tool execution.
It writes a permission request to ~/.qbraid/permissions/ and waits for a
response from the CLI watch mode or frontend dashboard.

Flow:
    1. Claude fires PreToolUse hook → this script receives tool info via stdin
    2. Script writes request to ~/.qbraid/permissions/<session-id>.request.json
    3. Script polls for ~/.qbraid/permissions/<session-id>.response.json
    4. If response arrives → return allow/deny to Claude
    5. If timeout → return "ask" (fall through to Claude's normal permission UI)
    6. If user is attached to tmux → return "ask" immediately

Exit codes:
    0 = allow (stdout JSON ignored for allow)
    2 = deny (stderr has reason)
    (no explicit "ask" exit code — we just exit 0 with no output to fall through)
"""

import json
import os
import sys
import time
from pathlib import Path

PERMISSIONS_DIR = Path.home() / ".qbraid" / "permissions"
POLL_INTERVAL = 0.5  # seconds
TIMEOUT = 30  # seconds — fall through to Claude's UI after this


def main():
    """Handle Claude Code PreToolUse permission hook via file-based request/response."""
    # Read hook input from stdin
    try:
        raw = sys.stdin.read().strip()
        if not raw:
            sys.exit(0)  # No input, allow
        data = json.loads(raw)
    except (json.JSONDecodeError, IOError):
        sys.exit(0)  # Parse error, allow

    session_id = data.get("session_id", "")
    tool_name = data.get("tool_name", "")
    tool_input = data.get("tool_input", {})
    cwd = data.get("cwd", "")
    hook_event = data.get("hook_event_name", "")

    # Only handle PreToolUse
    if hook_event != "PreToolUse":
        sys.exit(0)

    # Get QBRAID_SESSION_ID if set (for managed sessions)
    qbraid_sid = os.environ.get("QBRAID_SESSION_ID", session_id)

    # Check if anyone is watching this session (CLI watch or frontend).
    # The .watching file is created by the watch command and removed on exit.
    # If nobody is watching, fall through to Claude's native permission UI
    # immediately — no delay.
    watching_file = PERMISSIONS_DIR / f"{qbraid_sid}.watching"
    if not watching_file.exists():
        # Nobody watching — let Claude handle it natively
        sys.exit(0)

    # Create permissions directory
    PERMISSIONS_DIR.mkdir(parents=True, exist_ok=True)

    # Write the permission request
    request_file = PERMISSIONS_DIR / f"{qbraid_sid}.request.json"
    response_file = PERMISSIONS_DIR / f"{qbraid_sid}.response.json"

    # Clean up any stale response file
    if response_file.exists():
        response_file.unlink()

    request = {
        "session_id": qbraid_sid,
        "tool_name": tool_name,
        "tool_input": tool_input,
        "cwd": cwd,
        "timestamp": time.time(),
    }

    # Build a human-readable summary of what the tool wants to do
    if tool_name == "Bash":
        summary = tool_input.get("command", str(tool_input))
    elif tool_name in ("Write", "Edit"):
        summary = tool_input.get("file_path", str(tool_input))
    elif tool_name == "Read":
        summary = tool_input.get("file_path", str(tool_input))
    else:
        summary = str(tool_input)[:200]

    request["summary"] = summary

    try:
        request_file.write_text(json.dumps(request, indent=2))
    except IOError:
        sys.exit(0)  # Can't write, allow

    # Poll for response
    start = time.time()
    while (time.time() - start) < TIMEOUT:
        if response_file.exists():
            try:
                response = json.loads(response_file.read_text())
                decision = response.get("decision", "ask")

                # Clean up
                request_file.unlink(missing_ok=True)
                response_file.unlink(missing_ok=True)

                if decision == "allow":
                    # Output JSON to stdout to auto-approve
                    sys.stdout.write(
                        json.dumps(
                            {
                                "hookSpecificOutput": {
                                    "hookEventName": "PreToolUse",
                                    "permissionDecision": "allow",
                                    "permissionDecisionReason": "Approved via qBraid agent manager",
                                }
                            }
                        )
                    )
                    sys.exit(0)
                elif decision == "deny":
                    reason = response.get("reason", "Denied by qBraid agent manager")
                    sys.stderr.write(
                        json.dumps(
                            {
                                "decision": "deny",
                                "reason": reason,
                            }
                        )
                    )
                    sys.exit(2)
                else:
                    # "ask" — fall through to Claude's UI
                    sys.exit(0)

            except (json.JSONDecodeError, IOError):
                sys.exit(0)

        time.sleep(POLL_INTERVAL)

    # Timeout — clean up request file and fall through to Claude's UI
    request_file.unlink(missing_ok=True)
    sys.exit(0)


if __name__ == "__main__":
    main()
